import { Component, AfterViewInit, ChangeDetectorRef, ViewEncapsulation } from '@angular/core';
import { ButtonModule, CardModule, FormModule } from '@coreui/angular';
import { RouterLink, RouterOutlet } from '@angular/router';
import { Router } from '@angular/router';
import { CommonModule } from '@angular/common';

import { TagModule } from 'primeng/tag';
import { PaginatorModule } from 'primeng/paginator';
import { PaginatorState } from 'primeng/paginator';
import { TableModule } from 'primeng/table';
import { RatingModule } from 'primeng/rating';
import { ButtonModule as PrimeUIButtonModule } from 'primeng/button';
import { InputGroup } from 'primeng/inputgroup';
import { DialogModule } from 'primeng/dialog';
import { HttpClient, HttpClientModule } from '@angular/common/http';
import Quill from 'quill';

import { FileUploadModule } from 'primeng/fileupload';

import { ImageModule } from 'primeng/image';
import { FormsModule } from '@angular/forms';
import { InputTextModule } from 'primeng/inputtext';
import { EditorModule } from 'primeng/editor';
import { DomSanitizer, SafeHtml } from '@angular/platform-browser';
import { SelectModule } from 'primeng/select';
// ---
import { ConfirmDialogModule } from 'primeng/confirmdialog';
import { ConfirmationService, MessageService } from 'primeng/api';

import { ConfirmDialog } from 'primeng/confirmdialog';
import { ToastModule } from 'primeng/toast';

interface Blog {
  id: string;
  code: string;
  name: string;
  description: string;
  image: string;
  price: number;
  category: number;
  quantity: number;
  inventoryStatus: string;
  rating: number;
}

interface PageEvent {
  first: number;
  rows: number;
  page: number;
  pageCount: number;
}

@Component({
  selector: 'app-blog-management',
  imports: [
    CardModule,
    ButtonModule,
    TableModule,
    RatingModule,
    PrimeUIButtonModule,
    TagModule,
    PaginatorModule,
    FormModule,
    RouterOutlet,
    CommonModule,
    DialogModule,
    SelectModule,
    EditorModule,
    FileUploadModule,
    ImageModule,
    FormsModule,
    InputTextModule,
    HttpClientModule,
    ConfirmDialog,
    ToastModule,
    ButtonModule
  ],
  providers: [ConfirmationService, MessageService],
  templateUrl: './blog-management.component.html',
  styleUrl: './blog-management.component.scss',
  encapsulation: ViewEncapsulation.None
})
export class BlogManagementComponent {
  first: number = 0;
  rows: number = 10;
  isAddProductPage: boolean = false;
  visible: boolean = false;
  blogDetail: boolean = false;
  value: any;

  uploadedFiles: any[] = [];
  primaryImg: any;
  imageSrc: string = '';
  title = 'User';
  quill: any;
  delta: any;
  contentHtml: SafeHtml = '';
  editorInstance: any;

  blogContent: string = "<p><span style=\"background-color: rgb(255, 255, 255); color: rgb(68, 68, 68);\">Chả mực là món ăn đặc sản của vùng đất Hạ Long được làm từ nguyên liệu chính là thịt mực giã hoặc xay nhuyễn, tạo hình bánh tròn rồi chiên chín. Chả mực được biết đến như là một đặc sản nổi tiếng nhất của vùng đất Hạ Long, thường được người dân mua về làm quà. Chả mực được rất nhiều quý khách hàng ưa chuộng bởi chả mực ngon, bảo quản lâu và có quy trình thực hiện rất tỉ mỉ và kì công.</span></p><p><br></p><p class=\"ql-align-center\"><img src=\"data:image/png;base64,\"></p><p class=\"ql-align-center\"><br></p><p><span style=\"background-color: rgb(255, 255, 255); color: rgb(68, 68, 68);\">Chả mực giã tay – món ăn đặc sản của Quảng Ninh được làm từ mực tươi, đặc biệt là mực mai. Không những thế, mực mai phải được đánh bắt trong vùng Vịnh Hạ Long mới cho ra món chả mực có vị ngọt thơm đặc trưng của nơi này. Đây là điều làm nên tên gọi của món chả mực giã tay Quảng Ninh cũng như khiến món ăn này có hương vị thật sự khác biệt.</span></p><p><span style=\"background-color: rgb(255, 255, 255); color: rgb(68, 68, 68);\">Chả mực có rất nhiều chất dinh dưỡng. Trong 100g ăn được của mực tươi có đến 60,1g đạm và chỉ 4,5g chất béo. Ngoài ra mực có chứa một số chất khoáng vi lượng rất quý như sắt, kẽm, mangan… và cả testosterone tự nhiên có chức năng tăng cường sinh lực nam giới. Chả mực có tác dụng bồi bổ làm tăng sức khoẻ, tăng trí lực, đặc biệt có chứa các peptid có tác dụng chống độc và chất phóng xạ, không chỉ tốt cho sức khỏe mà còn ngăn ngừa được nhiều bệnh. Nếu bạn thắc mắc không biết mua chả mực ở đâu ngon, hấp dẫn. Liên hệ ngay Hải Sản Quảng Ninh để được hỗ trợ nhé</span></p>";

  constructor(
    private router: Router,
    private http: HttpClient,
    private sanitizer: DomSanitizer,
    private cdRef: ChangeDetectorRef,
    private confirmationService: ConfirmationService,
    private messageService: MessageService

  ) {
    this.router.events.subscribe(() => {
      this.isAddProductPage = this.router.url.includes('/blog-management/add-blog');
    });
  }

  toolbarOptions = [
    ['bold', 'italic', 'underline', 'strike'],
    ['blockquote', 'code-block'],
    ['link', 'image', 'video'],
    [{ 'header': 1 }, { 'header': 2 }],
    [{ 'list': 'ordered' }, { 'list': 'bullet' }, { 'list': 'check' }],
    [{ 'indent': '-1' }, { 'indent': '+1' }],
    [{ 'direction': 'rtl' }],
    [{ 'size': ['small', false, 'large', 'huge'] }],
    [{ 'header': [1, 2, 3, 4, 5, 6, false] }],
    [{ 'color': [] }, { 'background': [] }],
    [{ 'font': [] }],
    [{ 'align': [] }],
    ['clean']  // remove formatting button
  ];

  ngAfterViewChecked() {
    if (this.visible) {
      setTimeout(() => {
        if (!this.editorInstance) { // Đảm bảo không khởi tạo nhiều lần
          this.initializeQuill();
        }
      }, 100); // Đợi một khoảng thời gian để DOM cập nhật
    }
  }


  initializeQuill() {
    const quillContainer = document.getElementById('editorBlogManagement');
    if (quillContainer) {
      this.editorInstance = new Quill(quillContainer, {
        theme: 'snow',
        placeholder: 'Nhập mô tả truyện...',
        modules:{
          toolbar: this.toolbarOptions
        }
      });
    }
  }
  showDialog() {
    this.visible = true;
  }
  showBlogDetail() {
    this.blogDetail = true;
  }
  navigateToAddBlog() {
    this.router.navigate(['/blog-management/add-blog']);
  }
  onPageChange(event: PaginatorState) {
    this.first = event.first ?? 0;  // Đảm bảo giá trị không bị undefined
    this.rows = event.rows ?? 10;   // Đảm bảo giá trị không bị undefined
  }
  blog: Blog = {
    id: '1000',
    code: 'f230fh0g3',
    name: 'Bamboo Watch',
    description: 'Blog Description',
    image: 'bamboo-watch.jpg',
    price: 65,
    category: 12,
    quantity: 24,
    inventoryStatus: '15/02/2024',
    rating: 5
  };
  products!: Blog[];

  ngOnInit() {
    this.products = [this.blog]; // Thêm truyện vào danh sách để hiển thị
  }

  getSeverity(status: string): "success" | "danger" | "warn" | undefined {
    switch (status) {
      case 'INSTOCK':
        return 'success';
      case 'LOWSTOCK':
        return 'warn';
      case 'OUTOFSTOCK':
        return 'danger';
      default:
        return undefined; // Trả về undefined để tránh lỗi
    }
  }

  onUpload(event: any) {
    const file = event.files[0]; // Get the uploaded file

    // Create a URL for the uploaded image file
    const reader = new FileReader();
    reader.onload = (e: any) => {
      this.primaryImg = e.target.result; // Set the image source to the uploaded file's data URL
      console.log('Image Source:', this.primaryImg); // Check the image source in the console
    };
    reader.readAsDataURL(file); // Convert the file to a data URL for image preview
  }
  confirm_delete(event: Event) {
    this.confirmationService.confirm({
      target: event.target as EventTarget,
      message: 'Xác nhận xóa truyện ',
      header: 'Cảnh báo',
      icon: 'pi pi-info-circle',
      rejectLabel: 'Cancel',
      rejectButtonProps: {
        label: 'Hủy bỏ',
        severity: 'secondary',
        outlined: true,
      },
      acceptButtonProps: {
        label: 'Đồng ý',
        severity: 'danger',
      },

      accept: () => {
        this.messageService.add({ severity: 'info', summary: 'Confirmed', detail: 'Record deleted' });
      },
      reject: () => {
        this.messageService.add({ severity: 'error', summary: 'Rejected', detail: 'You have rejected' });
      },
    });
  }

  showContent() {
    if (this.editorInstance) {
      const content = this.editorInstance.root.innerHTML; // Lấy nội dung từ editor
      this.contentHtml = this.sanitizer.bypassSecurityTrustHtml(content);
      console.log(this.contentHtml);
    } else {
      console.error("Editor chưa được khởi tạo!");
    }
  }

}
